import random
class Node:
    __slots__ = ('v','pri','sz','l','r')
    def __init__(self, v):
        self.v = v; self.pri = random.random(); self.sz = 1; self.l = self.r = None

def sz(n): return n.sz if n else 0
def upd(n):
    if n: n.sz = 1 + sz(n.l) + sz(n.r)
def split(t, key):
    if not t: return None, None
    if t.v < key:
        a, b = split(t.r, key); t.r = a; upd(t); return t, b
    a, b = split(t.l, key); t.l = b; upd(t); return a, t
def merge(a, b):
    if not a or not b: return a or b
    if a.pri > b.pri:
        a.r = merge(a.r, b); upd(a); return a
    b.l = merge(a, b.l); upd(b); return b
def insert(t, v):
    a, b = split(t, v); return merge(merge(a, Node(v)), b)
def kth(t, k):
    while t:
        if sz(t.l) == k: return t.v
        if sz(t.l) > k: t = t.l
        else: k -= sz(t.l)+1; t = t.r
